+// RF-004: descuento por línea en porcentaje entero (0 a 100), aplicado antes del total y redondeado al centavo.
+// Aritmética entera: (subtotal * pct + 50) / 100 con división truncada redondea la mitad hacia arriba.
+function totalLinea(item) {
+  const subtotal = item.cantidad * item.precioUnitarioCentavos;
+  const pct = item.descuentoPorcentaje ?? 0;
+  if (!Number.isInteger(pct) || pct < 0 || pct > 100)
+    throw new RangeError("Descuento inválido: debe ser un entero de 0 a 100");
+  const descuentoCentavos = Math.floor((subtotal * pct + 50) / 100);
+  return subtotal - descuentoCentavos;
+}
